import { GoogleGenAI, Type } from "@google/genai";
import { Category, ProductInputs, PackagingRecommendation } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getPackagingRecommendation = async (
  category: Category,
  inputs: ProductInputs
): Promise<PackagingRecommendation> => {
  const prompt = `
    Analyze the following product details for a packaging recommendation in the '${category}' category:
    - Product Name: ${inputs.productName}
    - Weight: ${inputs.weight}
    - Fragility: ${inputs.fragility}
    - Water Resistance Required: ${inputs.waterResistance}
    - Max Acceptable Price: ${inputs.maxPrice}
    - Manufacturing Country: ${inputs.country}

    Strict Rules:
    - Recommend ONLY biodegradable and eco-friendly packaging materials.
    - Exclude plastics, thermocol, and non-sustainable composites.
    - Prioritize Low CO2 footprint and High biodegradability.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      systemInstruction: `
        You are EchoPack AI, an intelligent sustainability-focused packaging assistant.
        Your goal is to recommend only eco-friendly, biodegradable, and sustainable packaging materials.
        You must prioritize Sustainability, Low CO2 emissions, High biodegradability, Environmental safety, and Practical feasibility.
        Do not suggest plastic or non-recyclable materials.
        You must return the response in a structured JSON format.
      `,
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          materialName: { type: Type.STRING },
          suitability: { type: Type.STRING },
          sustainabilityBenefits: { type: Type.STRING },
          biodegradabilityLevel: { type: Type.STRING },
          co2Impact: { 
            type: Type.STRING, 
            description: "Must be 'Low', 'Very Low', or 'Neutral'" 
          },
          waterResistanceSuitability: { type: Type.STRING },
          costSuitability: { type: Type.STRING },
          countryAlignment: { type: Type.STRING },
          sustainabilityNote: { type: Type.STRING }
        },
        required: [
          'materialName', 'suitability', 'sustainabilityBenefits', 
          'biodegradabilityLevel', 'co2Impact', 'waterResistanceSuitability', 
          'costSuitability', 'countryAlignment', 'sustainabilityNote'
        ]
      }
    }
  });

  const resultText = response.text;
  if (!resultText) throw new Error("Empty response from AI");

  return JSON.parse(resultText) as PackagingRecommendation;
};

