const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.DASHBOARD);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [recommendation, setRecommendation] = useState<PackagingRecommendation | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleCategorySelect = (category: Category) => {
    setSelectedCategory(category);
    setState(AppState.FORM);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleFormSubmit = async (inputs: ProductInputs) => {
    if (!selectedCategory) return;

    setState(AppState.LOADING);
    setError(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });

    try {
      const result = await getPackagingRecommendation(selectedCategory, inputs);
      setRecommendation(result);
      setState(AppState.RESULT);
    } catch (err) {
      console.error(err);
      setError("Failed to generate recommendation. Please try again.");
      setState(AppState.FORM);
    }
  };

  const handleReset = () => {
    setState(AppState.DASHBOARD);
    setSelectedCategory(null);
    setRecommendation(null);
    setError(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 selection:bg-green-100 selection:text-green-900">
      <Header onHome={handleReset} />

