import { GoogleGenAI, Type } from "@google/genai";
import { Category, ProductInputs, PackagingRecommendation } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getPackagingRecommendation = async (
  category: Category,
  inputs: ProductInputs
): Promise<PackagingRecommendation> => {
  const prompt = `
    Analyze the following product details for a packaging recommendation in the '${category}' category:
    - Product Name: ${inputs.productName}
    - Weight: ${inputs.weight}
    - Fragility: ${inputs.fragility}
    - Water Resistance Required: ${inputs.waterResistance}
    - Max Acceptable Price: ${inputs.maxPrice} (The user provided this value in Indian Rupees - INR)
    - Manufacturing Country: ${inputs.country}

    Strict Rules:
